INSERT INTO "document_artifacts" ("id","tenant_id","source","processing_status","document_type","original_file","source_metadata","text_extraction","classification","normalized_metadata","security_flags","size_bytes","created_at","updated_at","deleted_at","suggested_fields","suggested_category_id") VALUES('9145f34a-c0b3-4bb5-9287-9b66620f1da5','default','manual_upload','abandoned','contract','{"fileId":"9145f34a-c0b3-4bb5-9287-9b66620f1da5","fileName":"IT_Service_Procurement.pdf","mimeType":"application/pdf","sizeBytes":4168,"storageRef":"uploads/document_artifact/default/2026-05-26/9145f34a-c0b3-4bb5-9287-9b66620f1da5-IT_Service_Procurement.pdf","checksum":"dd8fef03bbdb993e76d0425a77a31d65"}','{"manualUpload":{"uploadedBy":"52pIJmXZ5RnC4oXCIFsAzodyNBwBb2Ff","uploadedFrom":"ai_panel"}}','{"method":"manual","status":"success","text":"IT Service Procurement Contract Contract No.: HT-2026-IT-00387 Date: April 02, 2026 Contracting Parties Party A (Purchaser): Hangzhou Stellar Technology Group Co., Ltd. Address: No. 268 Wensan Road, Xihu District, Hangzhou, Zhejiang, China Party B (Supplier): Shenzhen CloudBridge Information Technology Co., Ltd. Address: No. 56 Keji South Road, Nanshan District, Shenzhen, Guangdong, China Article 1 Subject Matter and Scope of Services Party B shall provide Party A with enterprise ERP system deployment and maintenance services, including: 1. Deployment, configuration, and data migration of the ERP system (CloudBridge V5.0); 2. 12-month post-launch technical support and O&M assurance (24/7 response); 3. No fewer than 3 user training sessions, each at least 4 hours, covering Finance, Supply Chain, and HR modules. Article 2 Contract Price and Payment Terms Total contract price: USD 258,000.00 (tax inclusive, VAT at 6%). Payment schedule: 30% within 10 business days of contract execution; 50% upon successful acceptance; remaining 20% within 15 business days after the maintenance period expires. Article 3 Delivery and Acceptance Party B shall complete system deployment and submit an acceptance request within 90 calendar days of contract execution. Party A shall organize acceptance within 15 business days of receiving the request. Acceptance criteria shall be governed by Annex I: Technical Proposal and Acceptance Standards. Article 4 Liability for Breach If Party B fails to deliver on time, it shall pay liquidated damages of 0.05% of the total contract price per day of delay. If the delay exceeds 30 days, Party A may terminate this Contract. If Party A fails to make payment on time, it shall pay a late fee of 0.05% of the overdue amount per day of delay. Article 5 Confidentiality and Intellectual Property Both parties shall maintain confidentiality of trade secrets disclosed during contract performance for a period of 3 years after termination. IP rights of custom developments shall belong to Party A; standard product IP shall remain with Party B. Article 6 Dispute Resolution This Contract shall be governed by the laws of the People''s Republic of China. Disputes shall be resolved through negotiation; failing that, either party may submit the dispute to the Hangzhou Arbitration Commission. Party A (Seal): Party B (Seal): Authorized Representative: _______________ Authorized Representative: _______________ Date: ______/______/______ Date: ______/______/______ This Contract is executed in duplicate, with each party holding one copy of equal legal effect. Annexes form an integral part hereof.","confidence":0.9,"provider":"client_pdfjs"}','{"documentType":"contract","confidence":0.9,"possibleTypes":[{"documentType":"contract","confidence":0.9}],"reason":"The document is a contract between two parties, Hangzhou Stellar Technology Group Co., Ltd. and Shenzhen CloudBridge Information Technology Co., Ltd., outlining the terms and conditions of an IT service procurement.","modelId":"workers_ai","promptVersion":"document-intake-classify-v2","schemaVersion":"v2"}','{"abandonedAt":"2026-05-26T09:20:54.987Z","abandonedBy":"52pIJmXZ5RnC4oXCIFsAzodyNBwBb2Ff","abandonReason":"User abandoned from inbox review.","previousStatus":"ready_for_review","fileRetention":"retained_for_audit_cleanup"}','["untrusted_external_content"]',4168,'2026-05-26T09:20:32.579Z','2026-05-26T09:20:54.987Z',NULL,'{"fields":{"contract_number":"HT-2026-IT-00387","client_name":"Hangzhou Stellar Technology Group Co., Ltd.","effective_date":"2026-04-02","amount":258000,"currency":"USD","payment_terms":"30% within 10 business days of contract execution; 50% upon successful acceptance; remaining 20% within 15 business days after the maintenance period expires.","scope":"enterprise ERP system deployment and maintenance services"},"confidence":{"contract_number":1,"client_name":1,"effective_date":1,"expiry_date":1,"amount":1,"currency":1,"payment_terms":1,"scope":1},"evidence":[{"type":"extracted_field","refId":"workers_ai://contract_number","summary":"Extracted contract_number via workers_ai"},{"type":"extracted_field","refId":"workers_ai://client_name","summary":"Extracted client_name via workers_ai"},{"type":"extracted_field","refId":"workers_ai://effective_date","summary":"Extracted effective_date via workers_ai"},{"type":"extracted_field","refId":"workers_ai://amount","summary":"Extracted amount via workers_ai"},{"type":"extracted_field","refId":"workers_ai://currency","summary":"Extracted currency via workers_ai"},{"type":"extracted_field","refId":"workers_ai://payment_terms","summary":"Extracted payment_terms via workers_ai"},{"type":"extracted_field","refId":"workers_ai://scope","summary":"Extracted scope via workers_ai"}],"sourceQuotes":{"contractNumber":"Contract No.: HT-2026-IT-00387","clientName":"Party A (Purchaser): Hangzhou Stellar Technology Group Co., Ltd.","effectiveDate":"Date: April 02, 2026","amount":"Total contract price: USD 258,000.00","currency":"USD","paymentTerms":"Payment schedule: 30% within 10 business days of contract execution; 50% upon successful acceptance; remaining 20% within 15 business days after the maintenance period expires.","scope":"Party B shall provide Party A with enterprise ERP system deployment and maintenance services, including: 1. Deployment, configuration, and data migration of the ERP system (CloudBridge V5.0); 2. 12-month post-launch technical support and O&M assurance (24/7 response); 3. No fewer than 3 user training sessions, each at least 4 hours, covering Finance, Supply Chain, and HR modules."},"categoryId":"document_only.contract","extractedAt":"2026-05-26T09:20:43.275Z"}','document_only.contract');
